list_transactions.code:
use WebCommander\Resources\Transactions\Transactions;

$response = Transactions::listTransactions($client, ['limit' => 50, 'offset' => 0]);

foreach ($response->map['transactions'] as $transaction) {
    echo $transaction['transaction_no'], ' ', $transaction['total_records'], ' records', PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

get_transaction.code:
use WebCommander\Resources\Transactions\Transactions;

$response = Transactions::getTransaction($client, 'IMPORT-2026-0001');

echo $response->map['transaction_no'], ': ', $response->map['total_records'], ' records', PHP_EOL;
foreach ($response->map['by_type'] as $row) {
    echo $row['type'], ' ', $row['count'], PHP_EOL;
}

list_transaction_items.code:
use WebCommander\Resources\Transactions\Transactions;

$response = Transactions::listTransactionItems($client, 'IMPORT-2026-0001', [
    'type' => 'product', 'limit' => 20, 'offset' => 0, 'detail' => 'slim',
]);

foreach ($response->map['items'] as $item) {
    echo $item['id'], ' ', $item['name'], ' ', $item['sku'], PHP_EOL;
}
echo $response->map['pagination']['total'], ' in total', PHP_EOL;
